#!/usr/bin/env python3
"""
Harakat — Compact Arabic Diacritization
=======================================

A compact (3.14 MB) Arabic diacritization system achieving 4.46% DER.

Architecture:
  - v10 base model: Lexicon + rules + disambiguation (9.06% DER)
  - Error-correction layer: Triple-key correction trained on 17.7M error reports
  - Combined: 4.46% DER (51% relative improvement)

Novel Contributions:
  - Error-report training methodology (learns from base model failures, not corpus statistics)
  - Triple-key lookup: (base_word, predicted_form, context_signature) -> correction
  - Tiered confidence routing with regression blacklist

Model Statistics:
  - Total error reports:     17,756,272
  - Unique triple-keys:      10,820,679
  - Tier 1 entries:          83,745 (≥95% confidence)
  - Tier 1 ambiguous:        40,576 (context-dependent)
  - Tier 2 entries:          8,270  (≥85% confidence)
  - Dual-key entries:        157,007
  - Base fallback:           56,082
  - Blacklist:               683 words
  - LZMA compressed:         3.14 MB

Comparison:
  - 139x smaller than SUKOUN (2024 SOTA, 0.92% DER, ~436 MB)
  - 10x smaller than Shakkala/Shakkelha (~30 MB, ~2.7% DER)
  - Best accuracy-to-size ratio for edge deployment

Author: Jesse Morgan
        Staff Sergeant, U.S. Marine Corps
        Arabic Instructor, Defense Language Institute
License: MIT

Usage:
    from harakat import diacritize

    result = diacritize("كتب الطالب الدرس")
    print(result)  # كَتَبَ الطَّالِبُ الدَّرْسَ

Repository: https://github.com/jmorgan/harakat
"""

from __future__ import annotations

import re
import json
from dataclasses import dataclass, field
from typing import Optional, List, Dict, Tuple, Set
from enum import Enum, auto
from pathlib import Path


# =============================================================================
# ARABIC UNICODE CONSTANTS
# =============================================================================

class Arabic:
    """Arabic Unicode character constants and utilities."""
    
    # Diacritical marks (Harakat)
    FATHA = '\u064E'      # َ  (a)
    DAMMA = '\u064F'      # ُ  (u)
    KASRA = '\u0650'      # ِ  (i)
    SUKUN = '\u0652'      # ْ  (no vowel)
    SHADDA = '\u0651'     # ّ  (gemination)
    FATHATAN = '\u064B'   # ً  (an)
    DAMMATAN = '\u064C'   # ٌ  (un)
    KASRATAN = '\u064D'   # ٍ  (in)
    SUPERSCRIPT_ALEF = '\u0670'  # ٰ
    
    # All harakat
    HARAKAT = frozenset([
        FATHA, DAMMA, KASRA, SUKUN, SHADDA,
        FATHATAN, DAMMATAN, KASRATAN, SUPERSCRIPT_ALEF
    ])
    
    # Short vowels only
    SHORT_VOWELS = frozenset([FATHA, DAMMA, KASRA])
    
    # Tanween
    TANWEEN = frozenset([FATHATAN, DAMMATAN, KASRATAN])
    
    # Letters
    HAMZA = '\u0621'          # ء
    ALEF_MADDA = '\u0622'     # آ
    ALEF_HAMZA_ABOVE = '\u0623'  # أ
    WAW_HAMZA = '\u0624'      # ؤ
    ALEF_HAMZA_BELOW = '\u0625'  # إ
    YEH_HAMZA = '\u0626'      # ئ
    ALEF = '\u0627'           # ا
    BEH = '\u0628'            # ب
    TEH_MARBUTA = '\u0629'    # ة
    TEH = '\u062A'            # ت
    THEH = '\u062B'           # ث
    JEEM = '\u062C'           # ج
    HAH = '\u062D'            # ح
    KHAH = '\u062E'           # خ
    DAL = '\u062F'            # د
    THAL = '\u0630'           # ذ
    REH = '\u0631'            # ر
    ZAIN = '\u0632'           # ز
    SEEN = '\u0633'           # س
    SHEEN = '\u0634'          # ش
    SAD = '\u0635'            # ص
    DAD = '\u0636'            # ض
    TAH = '\u0637'            # ط
    ZAH = '\u0638'            # ظ
    AIN = '\u0639'            # ع
    GHAIN = '\u063A'          # غ
    FEH = '\u0641'            # ف
    QAF = '\u0642'            # ق
    KAF = '\u0643'            # ك
    LAM = '\u0644'            # ل
    MEEM = '\u0645'           # م
    NOON = '\u0646'           # ن
    HEH = '\u0647'            # ه
    WAW = '\u0648'            # و
    ALEF_MAKSURA = '\u0649'   # ى
    YEH = '\u064A'            # ي
    
    # Tatweel (kashida)
    TATWEEL = '\u0640'        # ـ
    
    # All Arabic letters
    LETTERS = frozenset([
        HAMZA, ALEF_MADDA, ALEF_HAMZA_ABOVE, WAW_HAMZA, ALEF_HAMZA_BELOW,
        YEH_HAMZA, ALEF, BEH, TEH_MARBUTA, TEH, THEH, JEEM, HAH, KHAH,
        DAL, THAL, REH, ZAIN, SEEN, SHEEN, SAD, DAD, TAH, ZAH, AIN, GHAIN,
        FEH, QAF, KAF, LAM, MEEM, NOON, HEH, WAW, ALEF_MAKSURA, YEH
    ])
    
    # Sun letters (for assimilation with ال)
    SUN_LETTERS = frozenset([
        TEH, THEH, DAL, THAL, REH, ZAIN, SEEN, SHEEN,
        SAD, DAD, TAH, ZAH, LAM, NOON
    ])
    
    # Moon letters
    MOON_LETTERS = LETTERS - SUN_LETTERS - {ALEF, ALEF_MADDA, ALEF_HAMZA_ABOVE, 
                                             ALEF_HAMZA_BELOW, ALEF_MAKSURA, 
                                             TEH_MARBUTA, HAMZA}
    
    @classmethod
    def is_arabic_letter(cls, char: str) -> bool:
        """Check if character is an Arabic letter."""
        return char in cls.LETTERS
    
    @classmethod
    def is_haraka(cls, char: str) -> bool:
        """Check if character is a diacritical mark."""
        return char in cls.HARAKAT
    
    @classmethod
    def is_sun_letter(cls, char: str) -> bool:
        """Check if letter is a sun letter."""
        return char in cls.SUN_LETTERS
    
    @classmethod
    def strip_harakat(cls, text: str) -> str:
        """Remove all diacritical marks from text."""
        return ''.join(c for c in text if c not in cls.HARAKAT)
    
    @classmethod
    def strip_tatweel(cls, text: str) -> str:
        """Remove tatweel (kashida) from text."""
        return text.replace(cls.TATWEEL, '')
    
    @classmethod
    def normalize(cls, text: str) -> str:
        """Normalize Arabic text for processing."""
        # Remove harakat
        text = cls.strip_harakat(text)
        # Remove tatweel
        text = cls.strip_tatweel(text)
        # Normalize alef variants
        text = re.sub(f'[{cls.ALEF_MADDA}{cls.ALEF_HAMZA_ABOVE}{cls.ALEF_HAMZA_BELOW}]', cls.ALEF, text)
        # Normalize yeh
        text = text.replace(cls.ALEF_MAKSURA, cls.YEH)
        return text


# =============================================================================
# DATA CLASSES
# =============================================================================

class Case(Enum):
    """Arabic grammatical cases (I'rab)."""
    NOMINATIVE = auto()   # مرفوع (marfoo')
    ACCUSATIVE = auto()   # منصوب (mansoob)
    GENITIVE = auto()     # مجرور (majroor)
    JUSSIVE = auto()      # مجزوم (majzoom)
    UNKNOWN = auto()


class WordType(Enum):
    """Arabic word types."""
    NOUN = auto()         # اسم
    VERB = auto()         # فعل
    PARTICLE = auto()     # حرف
    PROPER_NOUN = auto()  # اسم علم
    ADJECTIVE = auto()    # صفة
    PUNCTUATION = auto()  # علامات ترقيم
    UNKNOWN = auto()


class Dialect(Enum):
    """Arabic dialect variants."""
    MSA = auto()          # Modern Standard Arabic (فصحى)
    EGYPTIAN = auto()     # Egyptian Arabic (مصري)
    LEVANTINE = auto()    # Levantine Arabic (شامي)
    GULF = auto()         # Gulf Arabic (خليجي)
    MAGHREBI = auto()     # North African Arabic (مغاربي)
    AUTO = auto()         # Auto-detect dialect


@dataclass
class Token:
    """Represents a single Arabic token with analysis."""
    original: str
    normalized: str
    diacritized: str = ""
    word_type: WordType = WordType.UNKNOWN
    case: Case = Case.UNKNOWN
    root: str = ""
    pattern: str = ""
    confidence: float = 0.0
    is_definite: bool = False
    prefixes: List[str] = field(default_factory=list)
    suffixes: List[str] = field(default_factory=list)
    # إنّ sentence markers
    is_ism_inna: bool = False  # Subject of إنّ (accusative)
    is_khabar_inna: bool = False  # Predicate of إنّ (nominative)


@dataclass
class DiacritizationResult:
    """Result of diacritization operation."""
    text: str
    tokens: List[Token]
    confidence: float
    processing_time_ms: float = 0.0
    
    def to_dict(self) -> dict:
        """Convert to dictionary for JSON serialization."""
        return {
            'text': self.text,
            'confidence': self.confidence,
            'processing_time_ms': self.processing_time_ms,
            'tokens': [
                {
                    'original': t.original,
                    'diacritized': t.diacritized,
                    'word_type': t.word_type.name,
                    'case': t.case.name,
                    'root': t.root,
                    'confidence': t.confidence
                }
                for t in self.tokens
            ]
        }
    
    def __str__(self) -> str:
        return self.text


