def _load_context_rules():
    """Load bigram and trigram rules (embedded in this file)."""
    global _BIGRAM_RULES, _TRIGRAM_RULES

    if _BIGRAM_RULES is None:
        _BIGRAM_RULES = _EMBEDDED_BIGRAM_RULES

    if _TRIGRAM_RULES is None:
        _TRIGRAM_RULES = _EMBEDDED_TRIGRAM_RULES

    return _BIGRAM_RULES, _TRIGRAM_RULES


def _apply_context_rules(text: str) -> str:
    """
    Apply context rules (trigrams and bigrams) to improve diacritization.

    Trigrams (3-word context) take priority over bigrams (2-word context).
    """
    bigrams, trigrams = _load_context_rules()
    if not bigrams and not trigrams:
        return text

    words = text.split()
    if len(words) < 2:
        return text

    result_words = [words[0]]

    for i in range(1, len(words)):
        curr_word = words[i]
        curr_undiac = Arabic.normalize(Arabic.strip_harakat(curr_word))
        prev_undiac = Arabic.normalize(Arabic.strip_harakat(words[i - 1]))

        # Try trigram first (more context = more accurate)
        if i > 1 and trigrams:
            prev2_undiac = Arabic.normalize(Arabic.strip_harakat(words[i - 2]))
            tri_key = (prev2_undiac, prev_undiac, curr_undiac)
            if tri_key in trigrams:
                result_words.append(trigrams[tri_key])
                continue

        # Fall back to bigram
        bi_key = (prev_undiac, curr_undiac)
        if bi_key in bigrams:
            replacement = bigrams[bi_key]
            # Preserve hamza type for إن/أن variants (including prefixed forms وإن، فإن، etc.)
            curr_base = Arabic.strip_harakat(curr_word)
            if curr_undiac in ('ان', 'وان', 'فان', 'بان', 'لان', 'كان'):
                # Check if original has hamza below (إ) or above (أ)
                has_hamza_below = 'إ' in curr_base
                has_hamza_above = 'أ' in curr_base
                rep_has_hamza_below = 'إ' in replacement
                rep_has_hamza_above = 'أ' in replacement
                
                if has_hamza_below and rep_has_hamza_above:
                    # Original has إ (hamza below) - handle prefix-specific forms
                    # وإن = wa-in "and if" (conditional, NO shadda)
                    # فإن = fa-inna "for indeed" (emphatic, HAS shadda)
                    if curr_undiac == 'وان':
                        # وإن is always conditional - use sukun form
                        replacement = replacement.replace('وَأَنَّ', 'وَإِنْ').replace('وَأَنْ', 'وَإِنْ')
                    elif curr_undiac == 'فان':
                        # فإن - just convert hamza, keep original voweling
                        replacement = replacement.replace('فَأَنَّ', 'فَإِنَّ').replace('فَأَنْ', 'فَإِنْ')
                    elif curr_undiac == 'بان':
                        # بإن is usually emphatic - use shadda form  
                        replacement = replacement.replace('بِأَنَّ', 'بِإِنَّ').replace('بِأَنْ', 'بِإِنَّ')
                    else:
                        # Default: convert hamza, keep original voweling
                        replacement = replacement.replace('أَنْ', 'إنْ').replace('أَنَّ', 'إنَّ')
                elif has_hamza_above and rep_has_hamza_below:
                    # Original has أ, replacement has إ - convert back to أ
                    replacement = replacement.replace('إنْ', 'أَنْ').replace('إنَّ', 'أَنَّ').replace('وَإِنْ', 'وَأَنْ').replace('وَإِنَّ', 'وَأَنَّ').replace('فَإِنْ', 'فَأَنْ').replace('فَإِنَّ', 'فَأَنَّ')
            result_words.append(replacement)
        else:
            result_words.append(curr_word)

    return ' '.join(result_words)



# =============================================================================
# SYNTACTIC PARSER FOR CASE INFERENCE (Phase 2)
# =============================================================================

from enum import Enum as _Enum, auto as _auto

class _SyntacticRole(_Enum):
    """Grammatical role in sentence."""
    UNKNOWN = _auto()
    VERB = _auto()
    SUBJECT = _auto()      # فاعل - nominative
    OBJECT = _auto()       # مفعول به - accusative
    ISM_INNA = _auto()     # اسم إنّ - accusative
    KHABAR_INNA = _auto()  # خبر إنّ - nominative
    ISM_KANA = _auto()     # اسم كان - nominative
    KHABAR_KANA = _auto()  # خبر كان - accusative
    MUDAF = _auto()        # مضاف - case from context
    MUDAF_ILAYH = _auto()  # مضاف إليه - genitive
    MAJRUR = _auto()       # مجرور - genitive (after preposition)
    MUBTADA = _auto()      # مبتدأ - nominative
    KHABAR = _auto()       # خبر المبتدأ - nominative


class _Case(_Enum):
    """Arabic grammatical case."""
    NOMINATIVE = _auto()   # مرفوع - ُ
    ACCUSATIVE = _auto()   # منصوب - َ
    GENITIVE = _auto()     # مجرور - ِ
    UNKNOWN = _auto()


