        'جلس', 'جلست', 'وقف', 'وقفت', 'حمل', 'حملت',
        'وضع', 'وضعت', 'رفع', 'رفعت', 'نظر', 'نظرت',
        'سأل', 'سألت', 'أجاب', 'أجابت', 'طلب', 'طلبت',
        'وهب', 'منع', 'فرض', 'حرم', 'أحل', 'أوجب', 'أباح',
        'نفى', 'أثبت', 'بين', 'شرح', 'علم', 'علمت',
