_AN_DEFAULTS = {
    'ان': 'أَنَّ',      # Default to "that" - more common in classical texts
    'وان': 'وَإِنْ',    # Default to conditional
    'فان': 'فَإِنْ',    # Default to conditional
    'بان': 'بِأَنَّ',
    'لان': 'لِأَنَّ',
}

_NARRATION_VERBS = {'حدثنا', 'حدثني', 'اخبرنا', 'أخبرنا', 'انبأنا', 'أنبأنا', 'سمعت'}


class _EnhancedDisambiguator:
    """Enhanced pattern-based disambiguator for high-frequency ambiguous words."""

    @staticmethod
    def _normalize(text):
        """Normalize Arabic text for pattern matching."""
        if not text:
            return ''
        harakat = '\u064B\u064C\u064D\u064E\u064F\u0650\u0651\u0652\u0670'
        text = ''.join(c for c in text if c not in harakat)
        text = text.replace('أ', 'ا').replace('إ', 'ا').replace('آ', 'ا')
        text = text.replace('ى', 'ي')
        return text

    @classmethod
    def disambiguate_an(cls, word, prev, next_w):
        """Disambiguate إن/أن variants."""
        word_norm = cls._normalize(word)
        prev_norm = cls._normalize(prev)
        next_norm = cls._normalize(next_w)

        # Handle prefixed forms
        base = word_norm
        prefix = ''
        if word_norm.startswith('و') and len(word_norm) > 1:
            if word_norm in ('وان',):
                prefix = 'وَ'
                base = 'ان'
        elif word_norm.startswith('ف') and len(word_norm) > 1:
            if word_norm in ('فان',):
                prefix = 'فَ'
                base = 'ان'
        elif word_norm.startswith('ب') and len(word_norm) > 1:
            if word_norm in ('بان',):
                prefix = 'بِ'
                base = 'ان'
        elif word_norm.startswith('ل') and len(word_norm) > 1:
            if word_norm in ('لان',):
                prefix = 'لِ'
                base = 'ان'

        # Check bigram patterns
        bigram = (prev_norm, base)
        if bigram in _AN_PATTERNS:
            result = _AN_PATTERNS[bigram]
            if prefix:
                return prefix + result
            return result

        # Conditional trigram check: وان/فان + لم/لا/كان → إِنْ
        if next_norm in ('لم', 'لا', 'كان', 'كانت'):
            if word_norm == 'وان':
                return 'وَإِنْ'
            elif word_norm == 'فان':
                return 'فَإِنْ'

        # Return default
        return _AN_DEFAULTS.get(word_norm)

    @classmethod
    def disambiguate_min_man(cls, word, prev, next_w):
        """Disambiguate مَنْ vs مِنْ."""
        word_norm = cls._normalize(word)
        prev_norm = cls._normalize(prev)
        next_norm = cls._normalize(next_w)

        # Handle prefixed forms
        prefix = ''
        if word_norm == 'ومن':
            prefix = 'وَ'
        elif word_norm == 'فمن':
            prefix = 'فَ'

        # After quantifiers → مَنْ (whoever)
        if prev_norm in ('كل', 'لكل'):
            return prefix + 'مَنْ'

        # Partitive patterns → مِنْ (from)
        if prev_norm in ('شيء', 'شيئا', 'كثير', 'كثيرا', 'اكثر', 'أكثر',
                         'قليل', 'بعض', 'احد', 'واحد', 'جملة', 'عدد'):
            return prefix + 'مِنْ'

        # After prepositions → مِنْ
        if prev_norm in ('في', 'الى', 'إلى', 'ب', 'ل'):
            return prefix + 'مِنْ'

        # من followed by prepositional object (noun) → مِنْ
        if next_norm in ('غير', 'ذلك', 'هذا', 'هذه', 'ذا', 'هنا', 'هناك',
                         'اجل', 'أجل', 'قبل', 'بعد', 'عند', 'دون', 'فوق',
                         'تحت', 'بين', 'حيث', 'اين', 'جهة', 'ناحية'):
            return prefix + 'مِنْ'

        # من followed by definite noun (ال) → usually مِنْ (from)
        if next_norm.startswith('ال'):
            return prefix + 'مِنْ'

        # Default: مِنْ (from - more common overall)
        return prefix + 'مِنْ'

    @classmethod
    def disambiguate_ibn(cls, word, prev, prev2):
        """Disambiguate بن case endings."""
        prev_norm = cls._normalize(prev)
        prev2_norm = cls._normalize(prev2)

        # After narration verb (2 positions back) → nominative بْنُ
        if prev2_norm in _NARRATION_VERBS:
            return 'بْنُ'

        # After عن (2 positions back) → genitive بْنِ
        if prev2_norm == 'عن':
            return 'بْنِ'

        # In chain after بن → genitive بْنِ
        if prev_norm == 'بن':
            return 'بْنِ'

        # Default: genitive (most common in idafa)
        return 'بْنِ'

    @classmethod
    def disambiguate(cls, word, prev='', next_w='', prev2=''):
        """Main disambiguation entry point."""
        word_norm = cls._normalize(word)

        # إن/أن disambiguation
        if word_norm in ('ان', 'وان', 'فان', 'بان', 'لان'):
            return cls.disambiguate_an(word, prev, next_w)

        # من disambiguation
        if word_norm in ('من', 'ومن', 'فمن'):
            return cls.disambiguate_min_man(word, prev, next_w)

        # بن disambiguation
        if word_norm == 'بن':
            return cls.disambiguate_ibn(word, prev, prev2)

        return None


def _apply_enhanced_disambiguation(text):
    """Apply enhanced disambiguation - only for بن (requires prev2 context)."""
    words = text.split()
    if len(words) < 3:
        return text

    result = list(words)
    n = len(words)

    for i in range(2, n):  # Start from position 2 to have prev2
        word = words[i]
        word_undiac = Arabic.strip_harakat(word)
        word_norm = word_undiac.replace('أ', 'ا').replace('إ', 'ا').replace('آ', 'ا')

        # Only apply to بن - needs prev2 context for narration verbs
        if word_norm != 'بن':
            continue

        prev = words[i-1]
        prev2 = words[i-2]

        disambig = _EnhancedDisambiguator.disambiguate_ibn(word, prev, prev2)
        if disambig and disambig != word:
            result[i] = disambig

    return ' '.join(result)


