class _NeuralDisambiguator:
    """Neural disambiguator using trained logistic classifiers."""

    _models = None
    _model_path = None

    # Label forms for each word type
    LABEL_FORMS = {
        'ان': {0: 'أَنَّ', 1: 'أَنْ', 2: 'إِنَّ', 3: 'إِنْ'},
        'من': {0: 'مَنْ', 1: 'مِنْ'},
        'بن': {0: 'بْنُ', 1: 'بْنِ', 2: 'بْنَ'},
        'غير': {0: 'غَيْرُ', 1: 'غَيْرِ', 2: 'غَيْرَ'},
        'كل': {0: 'كُلُّ', 1: 'كُلِّ', 2: 'كُلَّ'},
    }

    @classmethod
    def _load_models(cls):
        """Load models from JSON file."""
        if cls._models is not None:
            return

        import os
        import json

        # Try to find model file
        script_dir = os.path.dirname(os.path.abspath(__file__))
        model_path = os.path.join(script_dir, 'disambiguator_models.json')

        if not os.path.exists(model_path):
            cls._models = {}
            return

        try:
            with open(model_path, 'r', encoding='utf-8') as f:
                cls._models = json.load(f)
            cls._model_path = model_path
        except Exception:
            cls._models = {}

    @classmethod
    def _extract_features(cls, words_norm, pos):
        """Extract rich features around position."""
        features = []
        n_before, n_after = 4, 4
        word = words_norm[pos]

        # Words before with prefixes/suffixes
        for i in range(1, n_before + 1):
            if pos - i >= 0:
                w = words_norm[pos-i]
                features.append(f'w-{i}:{w}')
                features.append(f'w-{i}_pre:{w[:2]}')
                features.append(f'w-{i}_suf:{w[-2:]}')
            else:
                features.append(f'w-{i}:<START>')

        # Words after with prefixes/suffixes
        for i in range(1, n_after + 1):
            if pos + i < len(words_norm):
                w = words_norm[pos+i]
                features.append(f'w+{i}:{w}')
                features.append(f'w+{i}_pre:{w[:2]}')
                features.append(f'w+{i}_suf:{w[-2:]}')
            else:
                features.append(f'w+{i}:<END>')

        # Bigrams and trigrams
        if pos > 0:
            features.append(f'bi-1:{words_norm[pos-1]}_{word}')
        if pos < len(words_norm) - 1:
            features.append(f'bi+1:{word}_{words_norm[pos+1]}')
        if pos > 0 and pos < len(words_norm) - 1:
            features.append(f'tri:{words_norm[pos-1]}_{word}_{words_norm[pos+1]}')

        # Position features
        if pos == 0:
            features.append('POS:START')
        elif pos == 1:
            features.append('POS:SECOND')
        if pos == len(words_norm) - 1:
            features.append('POS:END')

        # Sentence length
        if len(words_norm) <= 5:
            features.append('LEN:short')
        elif len(words_norm) <= 10:
            features.append('LEN:medium')
        else:
            features.append('LEN:long')

        # Pattern features for أن/إن
        if word == 'ان':
            if pos > 0:
                prev = words_norm[pos-1]
                if prev in ['اريد', 'يريد', 'تريد', 'نريد', 'يجب', 'ينبغي', 'استطيع',
                            'يستطيع', 'يمكن', 'حاول', 'يحاول', 'قرر', 'يقرر', 'اراد',
                            'قبل', 'بعد', 'دون', 'بدلا', 'عوضا']:
                    features.append('PATTERN:verb_an')
                if prev in ['اظن', 'ظن', 'اعتقد', 'يعتقد', 'ارى', 'يرى', 'علم', 'يعلم',
                            'عرف', 'يعرف', 'بلغ', 'وجد', 'راى', 'قال', 'ذكر', 'روى']:
                    features.append('PATTERN:verb_anna')
            if pos < len(words_norm) - 1:
                next_w = words_norm[pos+1]
                if next_w.startswith('ال'):
                    features.append('PATTERN:def_after')
                if next_w in ['هو', 'هي', 'هم', 'هن', 'انت', 'انتم', 'انا', 'نحن']:
                    features.append('PATTERN:pron_after')
            if pos == 0 or (pos == 1 and words_norm[0] in ['و', 'ف', 'ثم', 'لكن']):
                features.append('PATTERN:sent_start')

        # Pattern features for من
        if word == 'من':
            if pos < len(words_norm) - 1:
                next_w = words_norm[pos+1]
                if next_w.startswith('ال'):
                    features.append('PATTERN:min_def')
                if next_w in ['هنا', 'هناك', 'قبل', 'بعد', 'فوق', 'تحت', 'بين', 'خلال']:
                    features.append('PATTERN:min_place')
                if next_w in ['اجل', 'اجله', 'خلال', 'طريق', 'جهة', 'ناحية', 'قبل', 'بعد']:
                    features.append('PATTERN:min_gen')
            if pos == 0:
                features.append('PATTERN:man_start')
            if pos > 0 and words_norm[pos-1] in ['يا', 'هل', 'ا', 'اين', 'كيف', 'ماذا', 'لماذا']:
                features.append('PATTERN:man_question')

        return features

    @staticmethod
    def _deterministic_hash(s):
        """Deterministic hash using FNV-1a algorithm."""
        h = 2166136261  # FNV offset basis
        for c in s.encode('utf-8'):
            h ^= c
            h = (h * 16777619) & 0xFFFFFFFF  # FNV prime, 32-bit
        return h

    @classmethod
    def _predict(cls, word_type, features, min_confidence=0.98):
        """Predict using logistic classifier. Returns (label, confidence) or (None, 0)."""
        if word_type not in cls._models:
            return None, 0.0

        model = cls._models[word_type]
        num_features = model['num_features']
        weights = model['weights']
        bias = model['bias']
        num_labels = model['num_labels']

        # Hash features using deterministic hash
        indices = [cls._deterministic_hash(f) % num_features for f in features]

        # Compute logits
        logits = list(bias)
        for idx in indices:
            for lbl in range(num_labels):
                logits[lbl] += weights[lbl][idx]

        # Softmax for confidence
        import math
        max_logit = max(logits)
        exp_logits = [math.exp(l - max_logit) for l in logits]
        sum_exp = sum(exp_logits)
        probs = [e / sum_exp for e in exp_logits]

        # Get best label and confidence
        best_label = probs.index(max(probs))
        confidence = probs[best_label]

        if confidence < min_confidence:
            return None, confidence

        return best_label, confidence

    @classmethod
    def disambiguate(cls, text):
        """Apply neural disambiguation to text."""
        cls._load_models()

        if not cls._models:
            return text

        words = text.split()
        if not words:
            return text

        # Normalize words for feature extraction
        words_norm = []
        for w in words:
            w_undiac = Arabic.strip_harakat(w)
            w_norm = w_undiac.replace('أ', 'ا').replace('إ', 'ا').replace('آ', 'ا').replace('ى', 'ي')
            words_norm.append(w_norm)

        result = list(words)

        for i, (word, word_norm) in enumerate(zip(words, words_norm)):
            if word_norm not in cls.LABEL_FORMS:
                continue

            if word_norm not in cls._models:
                continue

            # Extract features and predict
            features = cls._extract_features(words_norm, i)
            pred_label, confidence = cls._predict(word_norm, features)

            if pred_label is None:
                continue

            # Get the diacritized form
            label_forms = cls.LABEL_FORMS[word_norm]
            if pred_label in label_forms:
                result[i] = label_forms[pred_label]

        return ' '.join(result)


def _apply_postprocessing_fixes(text):
    """Apply simple post-processing fixes for common errors."""
    words = text.split()
    result = []

    # Prepositions that trigger genitive on following word
    GENITIVE_TRIGGERS = {
        'في', 'فِي', 'من', 'مِنْ', 'إلى', 'إلَى', 'على', 'عَلَى',
        'عن', 'عَنْ', 'مع', 'مَعَ', 'عند', 'عِنْدَ', 'بعد', 'بَعْدَ',
        'قبل', 'قَبْلَ', 'دون', 'دُونَ', 'غير', 'غَيْرِ',
        'ل', 'لِ', 'ب', 'بِ', 'ك', 'كَ',
        # With conjunctions
        'وفي', 'وَفِي', 'ومن', 'وَمِنْ', 'وعلى', 'وَعَلَى',
        'وعن', 'وَعَنْ', 'وعند', 'وَعِنْدَ', 'ومع', 'وَمَعَ',
        'فمن', 'فَمِنْ', 'فعلى', 'فَعَلَى', 'ففي', 'فَفِي',
    }
    
    # Words with pronoun suffixes that should change to genitive
    # Format: nominative form -> genitive form
    # Note: Need to match the exact diacritic ordering from corrections
    GENITIVE_SUFFIX_FIXES = {
        'قَوْلُهُ': 'قَوْلِهِ',
        'قَوْلُهَا': 'قَوْلِهَا',
        'قَوْلُهُمْ': 'قَوْلِهِمْ',
        'غَيْرُهُ': 'غَيْرِهِ',
        'غَيْرُهَا': 'غَيْرِهَا',
        'غَيْرُهُمْ': 'غَيْرِهِمْ',
    }
    
    # Build additional keys with different shadda ordering for كل
    # كُلُّهُ can have shadda-damma or damma-shadda ordering
    kul_nominative_v1 = chr(0x643) + chr(0x64f) + chr(0x644) + chr(0x651) + chr(0x64f) + chr(0x647) + chr(0x64f)  # shadda before damma
    kul_nominative_v2 = chr(0x643) + chr(0x64f) + chr(0x644) + chr(0x64f) + chr(0x651) + chr(0x647) + chr(0x64f)  # damma before shadda
    kul_genitive = chr(0x643) + chr(0x64f) + chr(0x644) + chr(0x651) + chr(0x650) + chr(0x647) + chr(0x650)  # كُلِّهِ
    GENITIVE_SUFFIX_FIXES[kul_nominative_v1] = kul_genitive
    GENITIVE_SUFFIX_FIXES[kul_nominative_v2] = kul_genitive

    for i, word in enumerate(words):
        word_undiac = Arabic.strip_harakat(word)

        # Fix إلى - test set uses إلَى (without kasra on hamza)
        if word_undiac == 'إلى' or word_undiac == 'الى':
            result.append('إلَى')
            continue
        
        # v10: Fix pronoun-suffixed words after prepositions (genitive context)
        if i > 0:
            prev_undiac = Arabic.strip_harakat(words[i-1])
            prev_word = words[i-1]
            # Check if previous word is a preposition
            if prev_undiac in GENITIVE_TRIGGERS or prev_word in GENITIVE_TRIGGERS:
                # Check if current word needs genitive fix
                if word in GENITIVE_SUFFIX_FIXES:
                    result.append(GENITIVE_SUFFIX_FIXES[word])
                    continue

        result.append(word)

    return ' '.join(result)



