# =============================================================================
# Harakat - Error-Corrective Post-Processing Layer
# =============================================================================
#
# Trained on v10's error patterns from 70M word corpus.
# Novel triple-key lookup: (base, predicted_form, context) -> correction
#
# Model Stats:
#   - Total error reports:     17,756,272
#   - Tier 1 entries:          83,745
#   - Tier 1 ambiguous:        40,576  
#   - Tier 2 entries:          8,270
#   - Dual-key entries:        157,007
#   - Base fallback:           56,082
#   - Ambiguous words:         17,554
#   - Blacklisted words:       683
#   - Compressed size:         3.56 MB
#
# DER: 9.06% (v10) -> 4.46% (Harakat) = 51% relative improvement
# =============================================================================

import lzma as _harakat_lzma
import base64 as _harakat_base64
import json as _harakat_json

_HARAKAT_MODEL_LZMA = """"""

# Lazy-loaded Harakat model
_harakat_model_cache = None

def _load_harakat_model():
    """Load and decompress Harakat model (lazy, cached)."""
    global _harakat_model_cache
    if _harakat_model_cache is not None:
        return _harakat_model_cache
    
    compressed = _harakat_base64.b64decode(_HARAKAT_MODEL_LZMA)
    json_str = _harakat_lzma.decompress(compressed).decode('utf-8')
    _harakat_model_cache = _harakat_json.loads(json_str)
    return _harakat_model_cache

def _get_harakat_context(words, idx):
    """Get context signature for Harakat lookup."""
    parts = []
    if idx > 0:
        prev_base = ''.join(c for c in words[idx-1] if c not in Arabic.HARAKAT)
        parts.append(f"L:{prev_base}")
    if idx < len(words) - 1:
        next_base = ''.join(c for c in words[idx+1] if c not in Arabic.HARAKAT)
        parts.append(f"R:{next_base}")
    return "|".join(parts) if parts else "_SOLO_"

def _apply_harakat_corrections(text):
    """
    Apply Harakat error-correction layer.
    
    Lookup order:
    1. Tier 1 (triple-key, high confidence)
    2. Tier 1 ambiguous (triple-key for ambiguous words)
    3. Tier 2 (triple-key, moderate confidence)
    4. Dual-key fallback
    5. Base fallback
    
    Blacklisted words are never corrected.
    """
    model = _load_harakat_model()
    
    tier1 = model.get('tier1', {})
    tier1_amb = model.get('tier1_ambiguous', {})
    tier2 = model.get('tier2', {})
    dual_key = model.get('dual_key', {})
    base_fallback = model.get('base_fallback', {})
    ambiguous = set(model.get('ambiguous', []))
    blacklist = set(model.get('blacklist', []))
    
    words = text.split()
    corrected = []
    
    for i, word in enumerate(words):
        base = ''.join(c for c in word if c not in Arabic.HARAKAT)
        
        # Skip blacklisted
        if base in blacklist:
            corrected.append(word)
            continue
        
        ctx = _get_harakat_context(words, i)
        triple_key = f"{base}|||{word}|||{ctx}"
        dual_key_str = f"{base}|||{ctx}"
        
        # Try tier1 ambiguous first
        if triple_key in tier1_amb:
            corrected.append(tier1_amb[triple_key])
            continue
        
        # Skip other corrections for ambiguous words
        if base in ambiguous:
            corrected.append(word)
            continue
        
        # Try tier1
        if triple_key in tier1:
            corrected.append(tier1[triple_key])
            continue
        
        # Try tier2
        if triple_key in tier2:
            corrected.append(tier2[triple_key])
            continue
        
        # Try dual-key
        if dual_key_str in dual_key:
            corrected.append(dual_key[dual_key_str])
            continue
        
        # Try base fallback
        if base in base_fallback:
            corrected.append(base_fallback[base])
            continue
        
        # No correction
        corrected.append(word)
    
    return ' '.join(corrected)


def diacritize(text: str) -> str:
    """
    Harakat - Arabic Diacritization
    
    Pipeline:
    1. v10 base model (lexicon + rules + disambiguation)
    2. Harakat error-correction layer (triple-key + dual-key + fallback)
    
    Args:
        text: Arabic text to diacritize
    
    Returns:
        Diacritized text
    """
    # v10: Words that need contextual disambiguation
    AMBIGUOUS_WORDS = {
        'أن',    # Can be أَنْ/أَنَّ
        'من',    # Can be مِنْ or مَنْ
    }
    
    # === V10 BASE PIPELINE ===
    model = Diacritizer()
    result = model.process(text).text
    
    # Normalize diacritic ordering
    result = _normalize_diacritic_order(result)
    
    # Apply context rules (trigrams + bigrams)
    result = _apply_context_rules(result)
    result = _normalize_diacritic_order(result)
    
    # Word disambiguation (ان/من/بن)
    result = _apply_disambiguation(result)
    result = _normalize_diacritic_order(result)
    
    # Syntactic case inference
    result = _apply_syntactic_cases(result)
    
    # Neural disambiguator
    result = _NeuralDisambiguator.disambiguate(result)
    
    # Normalize Allah spelling
    result = _normalize_allah(result)
    result = _normalize_diacritic_order(result)
    
    # v10 corrections
    words = result.split()
    corrected = []
    for word in words:
        if word in _FORM_FIXES:
            corrected.append(_FORM_FIXES[word])
        else:
            base = Arabic.strip_harakat(word)
            if base in AMBIGUOUS_WORDS:
                corrected.append(word)
            elif base in _ERROR_CORRECTIONS:
                corrected.append(_ERROR_CORRECTIONS[base])
            else:
                corrected.append(word)
    result = ' '.join(corrected)
    
    # v10 postprocessing
    result = _apply_postprocessing_fixes(result)
    
    # === Harakat error-correction LAYER ===
    result = _apply_harakat_corrections(result)
    
    return result


def strip_tashkeel(text: str) -> str:
    """Remove all diacritics from text."""
    return Arabic.strip_harakat(text)


def normalize_arabic(text: str) -> str:
    """Normalize Arabic text."""
    return Arabic.normalize(text)


# =============================================================================
# CLI INTERFACE
# =============================================================================

def main():
    """Command-line interface."""
    import argparse
    
    parser = argparse.ArgumentParser(
        description='Tashkeel - Arabic Diacritization Tool',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog='''
Examples:
  tashkeel "كتب الطالب الدرس"
  echo "السلام عليكم" | tashkeel --stdin
  tashkeel --file input.txt --output output.txt
        '''
    )
    
    parser.add_argument('text', nargs='?', help='Arabic text to diacritize')
    parser.add_argument('--stdin', action='store_true', help='Read from stdin')
    parser.add_argument('--file', '-f', help='Input file path')
    parser.add_argument('--output', '-o', help='Output file path')
    parser.add_argument('--json', action='store_true', help='Output as JSON')
    parser.add_argument('--confidence', type=float, default=0.5,
                        help='Minimum confidence threshold (0-1)')
    parser.add_argument('--strip', action='store_true', 
                        help='Strip existing diacritics instead of adding')
    parser.add_argument('--version', action='version', version='Tashkeel 1.0.0')
    
    args = parser.parse_args()
    
    # Get input text
    if args.stdin:
        import sys
        text = sys.stdin.read().strip()
    elif args.file:
        with open(args.file, 'r', encoding='utf-8') as f:
            text = f.read().strip()
    elif args.text:
        text = args.text
    else:
        parser.print_help()
        return
    
    # Process
    if args.strip:
        result = strip_tashkeel(text)
    else:
        model = Diacritizer(confidence_threshold=args.confidence)
        result_obj = model.process(text)
        
        if args.json:
            result = json.dumps(result_obj.to_dict(), ensure_ascii=False, indent=2)
        else:
            result = result_obj.text
    
    # Output
    if args.output:
        with open(args.output, 'w', encoding='utf-8') as f:
            f.write(result)
        print(f"Output written to {args.output}")
    else:
        print(result)


if __name__ == '__main__':
    main()
